{"content": "// Cross-client DDR composition bench.
// CPU128 -> ddr_ui_adapt -> ddr_gpu_arb <- scanout/blitter -> native_memory.
// The scoreboard builds its byte image only from high-level operations and
// compares each client response with an independently computed request value.
`timescale 1ns/1ps
module bench;

    // ---------------------------------------------------------------------
    // Clock/reset and public DUT ports
    // ---------------------------------------------------------------------
    reg clk = 1'b0;
    always #5 clk = ~clk;

    reg rst_n = 1'b0;

    // 128-bit CPU side of the adapter.
    reg         u_cmd_en = 0;
    reg  [2:0]  u_cmd = 0;
    reg  [28:0] u_addr = 0;
    wire        u_cmd_ready;
    reg         u_wr_data_en = 0;
    reg         u_wr_data_end = 0;
    reg  [127:0] u_wr_data = 0;
    reg  [15:0]  u_wr_data_mask = 0;
    wire        u_wr_data_rdy;
    wire [127:0] u_rd_data;
    wire        u_rd_data_valid;
    wire        u_rd_data_end;

    // Adapter 256-bit IP side, wired to the arbiter CPU port.
    wire        ip_cmd_en;
    wire [2:0]  ip_cmd;
    wire [28:0] ip_addr;
    wire        ip_cmd_ready;
    wire        ip_wr_data_en;
    wire        ip_wr_data_end;
    wire [255:0] ip_wr_data;
    wire [31:0]  ip_wr_data_mask;
    wire         ip_wr_data_rdy;
    wire [255:0] ip_rd_data;
    wire         ip_rd_data_valid;
    wire         ip_rd_data_end;

    // Scanout producer.
    reg         g_valid = 0;
    reg  [28:0] g_addr = 0;
    wire        g_ready;
    wire [255:0] g_data;
    wire        g_data_valid;

    // Blitter/GPU producer.
    wire        b_valid;
    wire        b_write;
    wire [28:0] b_addr;
    wire [255:0] b_wr_data;
    wire [31:0] b_wr_mask;
    wire        b_ready;
    wire [255:0] b_rd_data;
    wire        b_rd_valid;

    // Ordered native terminal.
    wire        m_en;
    wire [2:0]  m_cmd;
    wire [28:0] m_addr;
    wire        m_ready;
    wire        m_wr_en;
    wire        m_wr_end;
    wire [255:0] m_wr_data;
    wire [31:0]  m_wr_mask;
    wire        m_wr_ready;
    wire [255:0] m_rd_data;
    wire        m_rd_valid;
    wire        m_rd_end;

    // ---------------------------------------------------------------------
    // DUT composition.
    // ---------------------------------------------------------------------
    ddr_ui_adapt u_adapter (
        .clk(clk), .rst_n(rst_n),
        .u_cmd_en(u_cmd_en), .u_cmd(u_cmd), .u_addr(u_addr),
        .u_cmd_ready(u_cmd_ready),
        .u_wr_data_en(u_wr_data_en), .u_wr_data_end(u_wr_data_end),
        .u_wr_data(u_wr_data), .u_wr_data_mask(u_wr_data_mask),
        .u_wr_data_rdy(u_wr_data_rdy),
        .u_rd_data(u_rd_data), .u_rd_data_valid(u_rd_data_valid),
        .u_rd_data_end(u_rd_data_end),
        .ip_cmd_en(ip_cmd_en), .ip_cmd(ip_cmd), .ip_addr(ip_addr),
        .ip_cmd_ready(ip_cmd_ready),
        .ip_wr_data_en(ip_wr_data_en), .ip_wr_data_end(ip_wr_data_end),
        .ip_wr_data(ip_wr_data), .ip_wr_data_mask(ip_wr_data_mask),
        .ip_wr_data_rdy(ip_wr_data_rdy),
        .ip_rd_data(ip_rd_data), .ip_rd_data_valid(ip_rd_data_valid),
        .ip_rd_data_end(ip_rd_data_end)
    );

    ddr_gpu_arb u_arb (
        .clk(clk), .rst_n(rst_n),
        .c_en(ip_cmd_en), .c_cmd(ip_cmd), .c_addr(ip_addr),
        .c_ready(ip_cmd_ready),
        .c_wr_en(ip_wr_data_en), .c_wr_end(ip_wr_data_end),
        .c_wr_data(ip_wr_data), .c_wr_mask(ip_wr_data_mask),
        .c_wr_ready(ip_wr_data_rdy),
        .c_rd_data(ip_rd_data), .c_rd_valid(ip_rd_data_valid),
        .c_rd_end(ip_rd_data_end),
        .g_valid(g_valid), .g_addr(g_addr), .g_ready(g_ready),
        .g_data(g_data), .g_data_valid(g_data_valid),
        .b_valid(b_valid && !suppress_request), .b_write(b_write), .b_addr(b_addr),
        .b_wr_data(b_wr_data), .b_wr_mask(b_wr_mask), .b_ready(b_ready),
        .b_rd_data(b_rd_data), .b_rd_valid(b_rd_valid),
        .m_en(m_en), .m_cmd(m_cmd), .m_addr(m_addr), .m_ready(m_ready),
        .m_wr_en(m_wr_en), .m_wr_end(m_wr_end), .m_wr_data(m_wr_data),
        .m_wr_mask(m_wr_mask), .m_wr_ready(m_wr_ready),
        .m_rd_data(m_rd_data), .m_rd_valid(m_rd_valid), .m_rd_end(m_rd_end)
    );

    native_memory u_native (
        .clk(clk), .resetn(rst_n), .hold_command(hold_command),
        .hold_write(hold_write), .hold_returns(hold_returns), .en(m_en), .cmd(m_cmd), .addr(m_addr),
        .ready(m_ready), .wr_en(m_wr_en), .wr_end(m_wr_end),
        .wr_data(m_wr_data), .wr_mask(m_wr_mask), .wr_ready(m_wr_ready),
        .rd_data(m_rd_data), .rd_valid(m_rd_valid), .rd_end(m_rd_end)
    );

    // Test-only fault controls. They are real top-level connections, never
    // force/deposit internal RTL state. Driver may only change these inputs.
    reg hold_command=0,hold_write=0,hold_returns=0;
    reg cut_feedback=0,suppress_request=0;
    reg start=0;
    reg [255:0] command=0;
    wire gpu_done,gpu_busy,target_valid;
    wire [31:0] rejected;
    integer gpu_done_count=0;
    gpu_v1 gpu(.clk(clk),.rst(!rst_n),.child_resetn({4{rst_n}}),
      .start(start),.command(command),.done(gpu_done),.busy(gpu_busy),
      .observe_packet_word0(),.target_config_valid(target_valid),
      .material_config_valid(),.rejected(rejected),.fragments(),.passed(),
      .texture_hits(),.texture_misses(),.valid(b_valid),.write(b_write),
      .addr(b_addr),.wr_data(b_wr_data),.wr_mask(b_wr_mask),
      .ready(b_ready && !cut_feedback && !suppress_request),
      .rd_valid(b_rd_valid),.rd_data(b_rd_data));
    always @(posedge clk) if(rst_n && gpu_done) gpu_done_count<=gpu_done_count+1;

    integer scenario=0,cycle=0,full_block_ready_cycles=0;
    reg cpu_begin=0;
    integer cpu_count=0,cpu_sent=0,scan_count=0;
    reg [31:0] cpu_words[0:31];
    initial $value$plusargs("case=%d",scenario);
    always @(posedge clk)begin
      cycle<=cycle+1;
      if(rst_n && u_arb.full && b_valid && m_ready && m_wr_ready)
        full_block_ready_cycles<=full_block_ready_cycles+1;
      if(cycle>12000)$fatal(1,"HARNESS bounded watchdog");
      if(rst_n && g_data_valid)scan_count<=scan_count+1;
    end
    // A serial CPU-side proxy: one upstream 128-bit beat per requested
    // 32-bit load, 32 loads over scratch128B. Real AE350/AHB/CDC not modeled.
    // We align to16B and select the corresponding 32-bit lane independently.
    initial begin : cpu_reader
      integer i,n; reg[31:0] word,expected;
      wait(cpu_begin); @(negedge clk);
      for(i=0;i<32;i=i+1)begin
        n=0;
        while(!u_cmd_ready && n<6000)begin @(negedge clk);n=n+1;end
        if(!u_cmd_ready)$fatal(1,"CPU request watchdog");
        u_cmd=1;u_addr=(32'h12000000+(i/4)*16)>>1;u_cmd_en=1;
        @(negedge clk);u_cmd_en=0;cpu_sent=cpu_sent+1;n=0;
        while(!u_rd_data_valid && n<6000)begin @(negedge clk);n=n+1;end
        if(!u_rd_data_valid)$fatal(1,"CPU response watchdog");
        word=u_rd_data[(i%4)*32+:32];
        expected=(32'h12000000+4*i)^32'ha5396c17;
        if(scenario!=5 && scenario!=7 && i>=8 && i<16)expected=32'h6b4d6b4d;
        if(word!==expected)$fatal(1,"CPU_DATA index%0d got%08x expected%08x",i,word,expected);
        cpu_words[i]=word;cpu_count=cpu_count+1;
        @(negedge clk);
      end
    end
    task automatic report(input string label);
      $display("OBS {\"case\":%0d,\"label\":\"%s\",\"cpu\":%0d,\"sent\":%0d,\"gpu_done\":%0d,\"busy\":%0d,\"rejected\":%0d,\"native_reads\":%0d,\"native_writes\":%0d,\"returned\":%0d,\"scan_returns\":%0d,\"full\":%0d,\"tags\":%0d,\"cpu_pending\":%0d,\"take_blitter\":%0d,\"prefer_blitter\":%0d,\"adapter_tags\":%0d,\"gpu_valid\":%0d,\"gpu_ready\":%0d,\"command_ready\":%0d,\"write_ready\":%0d,\"full_ready_cycles\":%0d,\"cycle\":%0d}",
        scenario,label,cpu_count,cpu_sent,gpu_done_count,gpu_busy,rejected,
        u_native.reads,u_native.writes,u_native.returned,scan_count,
        u_arb.full,(u_arb.wp-u_arb.rp)&31,u_arb.cpu_pending,
        u_arb.take_blitter,u_arb.prefer_blitter,(u_adapter.tq_w-u_adapter.tq_r)&31,
        b_valid,b_ready&&!cut_feedback&&!suppress_request,m_ready,m_wr_ready,full_block_ready_cycles,cycle);
    endtask
    // Driver implements reset, TARGET, CLEAR, faults and bounded observation.
    // Fixed test wrapper and above byte oracle remain read-only to the agent.
    `include "scenario.svh"
endmodule
"}

{"content": "`timescale 1ns/1ps
// Independent byte-addressed, in-order terminal. Not a model of PHY/calibration.
// Scratch range is checked before indexing; no truncation/alias of upper bits.
module native_memory(
 input wire clk, resetn, hold_command, hold_write, hold_returns,
 input wire en, input wire [2:0] cmd, input wire [28:0] addr,
 output wire ready, input wire wr_en,wr_end,
 input wire [255:0] wr_data, input wire [31:0] wr_mask,
 output wire wr_ready, output reg [255:0] rd_data=0,
 output reg rd_valid=0,rd_end=0
);
 localparam [31:0] BASE=32'h12000000;
 reg[7:0] bytes[0:127];
 reg[255:0] replies[0:255];
 integer due[0:255];
 integer tick=0,wp=0,rp=0,reads=0,writes=0,returned=0;
 integer i,base; reg[31:0] value;
 initial begin
  for(i=0;i<32;i=i+1) begin
   value=(BASE+4*i)^32'ha5396c17;
   bytes[4*i]=value[7:0];bytes[4*i+1]=value[15:8];
   bytes[4*i+2]=value[23:16];bytes[4*i+3]=value[31:24];
  end
 end
 assign ready=resetn && !hold_command && tick%7!=2;
 assign wr_ready=resetn && !hold_write && tick%5!=1;
 always @(posedge clk) begin
  if(!resetn) begin tick<=0;wp=0;rp=0;reads=0;writes=0;returned=0;rd_valid<=0;rd_end<=0;end
  else begin
   tick<=tick+1;rd_valid<=0;rd_end<=0;
   if(!hold_returns && rp<wp && tick>=due[rp])begin
    rd_data<=replies[rp];rd_valid<=1;rd_end<=1;rp=rp+1;returned=returned+1;
   end
   if(en)begin
    if(!ready)$fatal(1,"ENDPOINT command without ready");
    if(addr[2:0]!=0 || addr*4<BASE || addr*4>BASE+96)
     $fatal(1,"ENDPOINT address outside scratch128B");
    base=addr*4-BASE;
    if(cmd==0)begin
     if(!wr_en || !wr_end || !wr_ready)$fatal(1,"ENDPOINT missing write handshake");
     if(base!=32 || wr_mask!=0 || wr_data!={16{16'h6b4d}})
      $fatal(1,"ENDPOINT unexpected CLEAR footprint");
     for(i=0;i<32;i=i+1)bytes[base+i]=wr_data[i*8+:8];
     writes=writes+1;
    end else if(cmd==1)begin
     if(wp>=256)$fatal(1,"ENDPOINT queue bound");
     for(i=0;i<32;i=i+1)replies[wp][i*8+:8]=bytes[base+i];
     due[wp]=tick+4+(reads%4);wp=wp+1;reads=reads+1;
    end else $fatal(1,"ENDPOINT unknown command");
   end
   if(wr_en && !(en && cmd==0))$fatal(1,"ENDPOINT unmatched write data");
  end
 end
endmodule
"}

{"content": "// Bounded CPU-liveness scenarios for the real composition bench.
// Only top-level inputs are driven, and every drive change is made at negedge.
// The five fault flags are real bench inputs; no internal signal is forced.
// Internal values are only observed (report()/wait helpers) and never written.

// Native word address 0x12000060 / 4. It is eight-word aligned and inside the
// terminal's checked 128-byte scratch range. Used only as synthetic scan history.
localparam [28:0] SCAN_ADDR = 29'h04800018;

// ---------------------------------------------------------------------------
// Packet helpers. command/start are sampled by gpu_v1 on the next posedge.
// ---------------------------------------------------------------------------
task automatic pulse_packet(input [255:0] pkt);
    command = pkt;
    start   = 1'b1;
    @(negedge clk);
    start   = 1'b0;
endtask

task automatic send_target;
    // 16x1 target, colour base 0x12000020, Z base 0x12000040, stride 32.
    pulse_packet({32'd0, 32'd0, 32'd0, 32'h00200020,
                  32'h00100001, 32'h12000040, 32'h12000020, 32'h16000000});
endtask

task automatic send_clear;
    // opcode 0x1c, flags=1 (RGB565 colour), 0x6b4d, rectangle 16x1.
    pulse_packet({32'd0, 32'd0, 32'h00100001, 32'd0,
                  32'd0, 32'h6b4d, 32'd1, 32'h1c000000});
endtask

// ---------------------------------------------------------------------------
// Bounded observation helpers (read-only).
// ---------------------------------------------------------------------------
task automatic wait_gpu_done(input integer want);
    integer n;
    n = 0;
    while (gpu_done_count < want && n < 2000) begin
        @(negedge clk);
        n = n + 1;
    end
    if (gpu_done_count < want) $fatal(1, "scenario: GPU done timeout");
endtask

task automatic wait_cpu(input integer want);
    integer n;
    n = 0;
    while (cpu_count < want && n < 4000) begin
        @(negedge clk);
        n = n + 1;
    end
    if (cpu_count < want) $fatal(1, "scenario: CPU progress timeout");
endtask

task automatic wait_bvalid;
    integer n;
    n = 0;
    while (!b_valid && n < 1000) begin
        @(negedge clk);
        n = n + 1;
    end
    if (!b_valid) $fatal(1, "scenario: native VALID timeout");
endtask

task automatic wait_native_reads(input integer want);
    integer n;
    n = 0;
    while (u_native.reads < want && n < 2000) begin
        @(negedge clk);
        n = n + 1;
    end
    if (u_native.reads < want) $fatal(1, "scenario: native read timeout");
endtask

task automatic wait_native_writes(input integer want);
    integer n;
    n = 0;
    while (u_native.writes < want && n < 2000) begin
        @(negedge clk);
        n = n + 1;
    end
    if (u_native.writes < want) $fatal(1, "scenario: native write timeout");
endtask

task automatic wait_scan_returns(input integer want);
    integer n;
    n = 0;
    while (scan_count < want && n < 2000) begin
        @(negedge clk);
        n = n + 1;
    end
    if (scan_count < want) $fatal(1, "scenario: scan return timeout");
endtask

// ---------------------------------------------------------------------------
// Case 4 synthetic pending scan history.
// g_valid is held until exactly `count` real g_valid/g_ready accepts happened.
// Sampling at posedge counts the actual handshake; deassertion happens at the
// following negedge, so no extra request can be accepted.
// ---------------------------------------------------------------------------
task automatic scan_burst(input integer count);
    integer n;
    n = 0;
    g_addr  = SCAN_ADDR;
    g_valid = 1'b1;
    while (n < count) begin
        @(posedge clk);
        if (g_valid && g_ready) n = n + 1;
        @(negedge clk);
    end
    g_valid = 1'b0;
endtask

task automatic wait_arb_full_16reads;
    integer n;
    n = 0;
    while (!(u_arb.full && u_native.reads >= 16) && n < 2000) begin
        @(negedge clk);
        n = n + 1;
    end
    if (!(u_arb.full && u_native.reads >= 16))
        $fatal(1, "scenario: arbiter did not fill from 16 scan reads");
endtask

// ---------------------------------------------------------------------------
// Driver.
// ---------------------------------------------------------------------------
initial begin : scenario_driver
    repeat (8) @(negedge clk);
    rst_n = 1'b1;
    repeat (8) @(negedge clk);

    // Common TARGET. Wait for completion before any CLEAR scenario so that the
    // target configuration is exactly the protected 16x1/stride-32 packet.
    send_target();
    wait_gpu_done(1);
    if (!target_valid || rejected != 0) $fatal(1, "scenario: TARGET failed");

    case (scenario)
        // 0: healthy composition. CLEAR completes, then CPU does 32 reads.
        0: begin
            send_clear();
            wait_gpu_done(2);
            cpu_begin = 1'b1;
            wait_cpu(16);
            report("blocked");      // observation window: CLEAR finished
            wait_cpu(32);
            repeat (8) @(negedge clk);
            report("final");
        end

        // 1: terminal command channel held before CLEAR.
        1: begin
            hold_command = 1'b1;
            send_clear();
            wait_bvalid();
            cpu_begin = 1'b1;
            repeat (80) @(negedge clk);   // >=80 cycles with CLEAR held
            report("blocked");
            hold_command = 1'b0;
            wait_cpu(32);
            wait_gpu_done(2);
            repeat (8) @(negedge clk);
            report("final");
        end

        // 2: terminal write channel held before CLEAR. The command port is
        // available, but the blitter write cannot be accepted, so CPU reads
        // are stalled despite command_ready remaining high.
        2: begin
            hold_write = 1'b1;
            send_clear();
            wait_bvalid();
            cpu_begin = 1'b1;
            repeat (80) @(negedge clk);
            report("blocked");
            hold_write = 1'b0;
            wait_cpu(32);
            wait_gpu_done(2);
            repeat (8) @(negedge clk);
            report("final");
        end

        // 3: feedback cut before CLEAR. The arbiter/terminal keep accepting
        // blitter writes repeatedly, but the GPU never observes b_ready.
        3: begin
            cut_feedback = 1'b1;
            send_clear();
            wait_bvalid();
            repeat (40) @(negedge clk);   // >=40 cycles before starting CPU
            wait_native_writes(2);
            cpu_begin = 1'b1;
            wait_cpu(8);
            report("blocked");
            wait_cpu(32);
            repeat (8) @(negedge clk);
            report("final");              // cut_feedback still asserted
        end

        // 4: synthetic pending scan history. hold_returns prevents any reply,
        // so the arbiter fills with 16 queued read tags.
        4: begin
            hold_returns = 1'b1;
            scan_burst(16);
            wait_arb_full_16reads();
            send_clear();
            wait_bvalid();  // Observe CLEAR native request, not its decode latency.
            cpu_begin = 1'b1;
            repeat (80) @(negedge clk);
            report("blocked");            // full=1, tags=16, native VALID held
            hold_returns = 1'b0;
            wait_cpu(32);
            wait_scan_returns(16);
            wait_gpu_done(2);
            repeat (8) @(negedge clk);
            report("final");
        end

        // 5: GPU native VALID is withheld from the arbiter (and its feedback is
        // withheld). CPU reads still use unchanged seed memory.
        5: begin
            suppress_request = 1'b1;
            send_clear();
            wait_bvalid();
            cpu_begin = 1'b1;
            wait_cpu(32);
            repeat (8) @(negedge clk);
            report("blocked");
            repeat (8) @(negedge clk);
            report("final");
        end

        // 6: feedback cut plus held returns. Writes keep being accepted while
        // exactly one CPU read is outstanding with a missing return.
        6: begin
            cut_feedback = 1'b1;
            hold_returns = 1'b1;
            send_clear();
            wait_bvalid();
            wait_native_writes(2);
            cpu_begin = 1'b1;
            wait_native_reads(1);
            repeat (80) @(negedge clk);   // >=80 cycles with return held
            report("blocked");
            hold_returns = 1'b0;          // release returns only
            wait_cpu(32);
            repeat (8) @(negedge clk);
            report("final");              // cut_feedback still asserted
        end

        // 7: request suppression plus write-channel hold. CPU reads complete,
        // while no GPU write reaches the terminal at any point.
        7: begin
            suppress_request = 1'b1;
            hold_write       = 1'b1;
            send_clear();
            wait_bvalid();
            cpu_begin = 1'b1;
            wait_cpu(32);
            repeat (8) @(negedge clk);
            report("blocked");
            repeat (8) @(negedge clk);
            report("final");              // both faults still asserted
        end

        default: $fatal(1, "scenario: unsupported case %0d", scenario);
    endcase

    $finish;
end
"}

{"content": "// Shared native DDR3 UI: CPU adapter, scanout reads and blitter reads/writes.
// Addresses are 32-bit words, aligned to eight words (32 bytes).
// CPU upstream issues command+data pulses only when ready; capture them in a
// one-entry buffer to break the ready chain through the legacy CPU adapter.
// Scanout has priority for bounded line fetches; CPU/blitter alternate otherwise.
// Their grant is registered, so changing clients may insert an idle cycle.
`default_nettype none
module ddr_gpu_arb (
    input wire clk, rst_n,
    input wire c_en,
    input wire [2:0] c_cmd,
    input wire [28:0] c_addr,
    output wire c_ready,
    input wire c_wr_en, c_wr_end,
    input wire [255:0] c_wr_data,
    input wire [31:0] c_wr_mask,
    output wire c_wr_ready,
    output wire [255:0] c_rd_data,
    output wire c_rd_valid, c_rd_end,
    input wire g_valid,
    input wire [28:0] g_addr,
    output wire g_ready,
    output wire [255:0] g_data,
    output wire g_data_valid,
    input wire b_valid, b_write,
    input wire [28:0] b_addr,
    input wire [255:0] b_wr_data,
    input wire [31:0] b_wr_mask,
    output wire b_ready,
    output wire [255:0] b_rd_data,
    output wire b_rd_valid,
    output wire m_en,
    output wire [2:0] m_cmd,
    output wire [28:0] m_addr,
    input wire m_ready,
    output wire m_wr_en, m_wr_end,
    output wire [255:0] m_wr_data,
    output wire [31:0] m_wr_mask,
    input wire m_wr_ready,
    input wire [255:0] m_rd_data,
    input wire m_rd_valid, m_rd_end
);
    reg [1:0] tags [0:15]; // 0 CPU, 1 scanout, 2 blitter
    reg [4:0] wp = 0, rp = 0;
    reg full = 0;
    wire empty = wp == rp;
    wire issue = rst_n && !full;
    reg cpu_pending = 0;
    reg [2:0] cpu_cmd;
    reg [28:0] cpu_addr;
    reg [255:0] cpu_data;
    reg [31:0] cpu_mask;
    reg prefer_blitter = 1;
    reg take_blitter = 0;
    // Two scanout request slots isolate its distant owner/request decode
    // from DDR arbitration. READY acknowledges enqueueing; responses still
    // follow DDR issue order. The FIFO sustains one request per cycle when
    // DDR accepts continuously, and never depends on DDR READY at its input.
    reg [28:0] scan_addresses [0:1];
    reg scan_wp=0,scan_rp=0;
    reg [1:0] scan_count=0;
    wire scan_valid=scan_count!=0;
    wire [28:0] scan_addr=scan_addresses[scan_rp];
    assign g_ready = rst_n && scan_count!=2;
    wire scan_enqueue=g_valid && g_ready;
    wire scan_issue=scan_valid && issue && m_ready;
    always @(posedge clk)begin
        if(!rst_n)begin scan_wp<=0;scan_rp<=0;scan_count<=0;end
        else begin
            if(scan_enqueue)begin scan_addresses[scan_wp]<=g_addr;scan_wp<=!scan_wp;end
            if(scan_issue)scan_rp<=!scan_rp;
            case({scan_enqueue,scan_issue})
                2'b10:scan_count<=scan_count+1'b1;
                2'b01:scan_count<=scan_count-1'b1;
                default:;
            endcase
        end
    end
    // b_grant est gardé tel quel par la synthèse (syn_keep) : sans cela, la LUT de b_ready était partagée
    // avec m_wr_en, qui dépend de b_valid, et l'analyse de timing comptait une boucle combinatoire
    // b_valid -> arbitre -> b_ready -> blitter/V1 qui n'existe pas logiquement (r600, -0,47 ns).
    wire b_grant /* synthesis syn_keep=1 */ = issue && !scan_valid && take_blitter && m_ready && (!b_write || m_wr_ready);
    assign b_ready = b_grant;
    assign c_ready = rst_n && !cpu_pending;
    assign c_wr_ready = c_ready;
    wire cpu_fire = issue && !scan_valid && !take_blitter && cpu_pending && m_ready && (cpu_cmd != 0 || m_wr_ready);
    assign m_en = scan_issue || (b_valid && b_ready) || cpu_fire;
    assign m_cmd = scan_valid ? 3'b001 : take_blitter ? {2'b0,!b_write} : cpu_cmd;
    assign m_addr = scan_valid ? scan_addr : take_blitter ? b_addr : cpu_addr;
    assign m_wr_en = (b_valid && b_ready && b_write) || (cpu_fire && cpu_cmd == 0);
    assign m_wr_end = m_wr_en;
    assign m_wr_data = take_blitter ? b_wr_data : cpu_data;
    assign m_wr_mask = take_blitter ? b_wr_mask : cpu_mask;
    wire push = scan_issue || (b_valid && b_ready && !b_write) || (cpu_fire && cpu_cmd == 1);
    wire pop = m_rd_valid && !empty;
    wire [4:0] next_wp = wp + {4'b0, push};
    wire [4:0] next_rp = rp + {4'b0, pop};
    wire [4:0] incremented_wp = wp + 5'd1;
    wire one_slot_left = incremented_wp == {~rp[4],rp[3:0]};
    always @(posedge clk) begin
        if (!rst_n) begin
            wp <= 0; rp <= 0; full <= 0; prefer_blitter <= 1;
            take_blitter<=0;
            cpu_pending <= 0; cpu_cmd <= 0; cpu_addr <= 0; cpu_data <= 0; cpu_mask <= 32'hffffffff;
        end
        else begin
            // Cut the valid -> arbitration -> ready round trip. A stale grant
            // can only insert a bubble: native commands still require valid.
            // Acknowledgement remains the actual DDR command/data acceptance.
            if(b_valid && b_ready) take_blitter<=0;
            else take_blitter<=b_valid && (prefer_blitter || !cpu_pending);
            // While empty, sample the payload independently of the late
            // upstream request. The acceptance cycle captures the same words;
            // once pending, every word remains held until DDR accepts it.
            // This leaves c_en driving only the valid bit, not 320 payload CEs.
            if (!cpu_pending) begin
                cpu_cmd <= c_cmd; cpu_addr <= c_addr;
                cpu_data <= c_wr_data; cpu_mask <= c_wr_mask;
            end
            if (c_en && c_ready) cpu_pending <= 1;
            else if (cpu_fire) cpu_pending <= 0;
            if (!scan_valid) begin
                if (b_valid && b_ready) prefer_blitter <= 0;
                else if (cpu_fire) prefer_blitter <= 1;
            end
            if (push) tags[wp[3:0]] <= scan_valid ? 2'd1 : take_blitter ? 2'd2 : 2'd0;
            wp <= next_wp; rp <= next_rp;
            // Compare stable pointers before the late command acceptance.
            // Simultaneous push/pop leaves occupancy unchanged.
            if(push && !pop)full<=one_slot_left;
            else if(pop && !push)full<=0;
        end
    end
    assign c_rd_data = m_rd_data;
    assign g_data = m_rd_data;
    assign c_rd_valid = pop && tags[rp[3:0]] == 0;
    assign c_rd_end = c_rd_valid && m_rd_end;
    assign g_data_valid = pop && tags[rp[3:0]] == 1;
    assign b_rd_data = m_rd_data;
    assign b_rd_valid = pop && tags[rp[3:0]] == 2;
endmodule
`default_nettype wire
"}

{"content": "// ddr_ui_adapt.v — adaptateur de largeur entre l'interface utilisateur « 16 bits » (128 bits par rafale, adresses en
// mots de 16 bits, sémantique du contrôleur DDR3 Gowin en DQ 16 telle que modélisée dans sim/ddr3_ui_model.py et
// validée sur carte en E1/E2) et l'IP DDR3 configurée en DQ 32 bits (256 bits par rafale, adresses en mots de 32 bits,
// 1 Go) — ARCHI_V3 § 11 (E2-f1). Il permet de garder le pont Sipeed, ddr_arb et ddr_writer tels quels.
//
// Sémantique reproduite (côté amont, « u_* ») :
//   - adresse u_addr en mots de 16 bits ; une rafale couvre les 16 octets à (u_addr & ~7) × 2 ; si u_addr n'est pas
//     alignée, la donnée écrite et le masque sont TOURNÉS de (u_addr & 7) mots (c'est ce que faisait le contrôleur
//     16 bits : « la donnée présentée commence au mot demandé »), et une lecture rend la rafale tournée en sens
//     inverse (mot demandé en tête) ;
//   - masque : 1 = octet non écrit.
// Côté IP 32 bits (« ip_* ») : commandes toujours ALIGNÉES sur la rafale de 32 octets (ip_addr = octets / 4 avec les
// 3 bits bas à 0) ; la moitié de 128 bits visée est u_addr[3] (octet 16 de la rafale), l'autre moitié est masquée.
// Hypothèse à vérifier sur carte : rafale alignée = 8 mots de 32 bits en petit-boutiste (mot 0 en bas), comme en 16 bits.
// Lectures : l'IP rend dans l'ordre → file d'étiquettes {moitié, rotation} ; cmd_ready amont = IP prête ET file non
// pleine (jamais de commande perdue en silence). Données d'écriture : wr_data_en passe tel quel (l'IP les apparie).
`default_nettype none
module ddr_ui_adapt #(
    parameter TAG_LOG2 = 4                  // 16 lectures en vol au plus (le pont n'en a qu'une, le writer aucune)
) (
    input  wire         clk,
    input  wire         rst_n,
    // amont : interface 128 bits (sortie de ddr_arb)
    input  wire         u_cmd_en,
    input  wire [2:0]   u_cmd,
    input  wire [28:0]  u_addr,
    output wire         u_cmd_ready,
    input  wire         u_wr_data_en,
    input  wire         u_wr_data_end,
    input  wire [127:0] u_wr_data,
    input  wire [15:0]  u_wr_data_mask,
    output wire         u_wr_data_rdy,
    output wire [127:0] u_rd_data,
    output wire         u_rd_data_valid,
    output wire         u_rd_data_end,
    // aval : IP DDR3 en DQ 32 (256 bits)
    output wire         ip_cmd_en,
    output wire [2:0]   ip_cmd,
    output wire [28:0]  ip_addr,
    input  wire         ip_cmd_ready,
    output wire         ip_wr_data_en,
    output wire         ip_wr_data_end,
    output wire [255:0] ip_wr_data,
    output wire [31:0]  ip_wr_data_mask,
    input  wire         ip_wr_data_rdy,
    input  wire [255:0] ip_rd_data,
    input  wire         ip_rd_data_valid,
    input  wire         ip_rd_data_end
);
    // --- rotation d'un mot de 128 bits par n mots de 16 bits (gauche pour écrire, droite pour lire) -------------
    function [127:0] rotl128; input [127:0] d; input [2:0] n;
        begin rotl128 = (d << (16 * n)) | (d >> (128 - 16 * n)); end
    endfunction
    function [127:0] rotr128; input [127:0] d; input [2:0] n;
        begin rotr128 = (d >> (16 * n)) | (d << (128 - 16 * n)); end
    endfunction
    function [15:0] rotl16; input [15:0] m; input [2:0] n;
        begin rotl16 = (m << (2 * n)) | (m >> (16 - 2 * n)); end
    endfunction

    // --- file d'étiquettes des lectures en vol ------------------------------------------------------------------
    localparam DEPTH = 1 << TAG_LOG2;
    reg  [3:0]          tags [0:DEPTH-1];                    // {half, rot}
    reg  [TAG_LOG2:0]   tq_w = 0, tq_r = 0;
    // `tq_full` REGISTRÉ (calculé sur les pointeurs du cycle suivant) : combinatoire, il entrait dans u_cmd_ready →
    // arbitre → mux de données 256 bits → tampon d'écriture de l'IP, chemin en violation de 1 ns (E2-f1, sdc corrigé).
    // Pessimiste d'un cycle sur la libération d'une place (16 lectures en vol, le pont n'en a qu'une) : sans effet.
    reg                 tq_full = 1'b0;
    wire                tq_empty = (tq_w == tq_r);
    assign u_cmd_ready = ip_cmd_ready && !tq_full;
    wire   push = u_cmd_en && u_cmd_ready && (u_cmd == 3'b001);
    wire   pop  = ip_rd_data_valid;
    wire [TAG_LOG2:0] tq_w_n = tq_w + {{TAG_LOG2{1'b0}}, push};
    wire [TAG_LOG2:0] tq_r_n = tq_r + {{TAG_LOG2{1'b0}}, pop};
    wire [TAG_LOG2:0] tq_count = tq_w - tq_r;
    always @(posedge clk) begin
        if (!rst_n) begin
            tq_w <= 0; tq_r <= 0; tq_full <= 1'b0;
        end else begin
            // The write slot is free whenever the queue is not full. Prepare
            // its tag every such cycle; only push publishes it by advancing
            // tq_w. Never overwrite this slot while full: it is then the head.
            // This removes upstream arbitration from the RAM write enable.
            if (!tq_full) tags[tq_w[TAG_LOG2-1:0]] <= {half, rot};
            tq_w <= tq_w_n; tq_r <= tq_r_n;
            // L11 : même valeur que (tq_w_n, tq_r_n) « écart = DEPTH », calculée sur les pointeurs courants ; push et
            // pop, qui arrivent tard (arbitre, IP), ne font plus que choisir entre trois comparaisons déjà prêtes.
            tq_full <= (push && !pop) ? tq_count == DEPTH - 1 : (!push && pop) ? tq_count == DEPTH + 1 : tq_count == DEPTH;
        end
    end
    /* verilator lint_off UNUSEDSIGNAL */
    wire tq_underflow = pop && tq_empty;                     // donnée rendue sans lecture en vol : incohérence (banc)
    /* verilator lint_on UNUSEDSIGNAL */

    // --- commande --------------------------------------------------------------------------------------------
    // Le masque et la donnée d'écriture dépendent de l'adresse de la commande : le pont et le writer présentent
    // wr_data_en au même cycle que cmd_en (ddr_arb : ui_wr_data_end = ui_wr_data_en), on utilise donc u_addr du cycle.
    wire [2:0] rot  = u_addr[2:0];
    wire       half = u_addr[3];
    // Contrat amont (celui de ddr_arb) : u_cmd_en seulement quand u_cmd_ready ; on verrouille quand même la file
    // pleine côté IP pour qu'une lecture sans étiquette ne puisse jamais partir (désynchronisation silencieuse).
    assign ip_cmd_en = u_cmd_en && !tq_full;
    assign ip_cmd    = u_cmd;
    assign ip_addr   = {1'b0, u_addr[28:4], 3'b000};        // octets / 4, aligné sur la rafale de 32 octets
    wire [127:0] wdata_eff = rotl128(u_wr_data, rot);
    wire [15:0]  wmask_eff = rotl16(u_wr_data_mask, rot);
    assign ip_wr_data      = {wdata_eff, wdata_eff};
    assign ip_wr_data_mask = half ? {wmask_eff, 16'hFFFF} : {16'hFFFF, wmask_eff};
    assign ip_wr_data_en   = u_wr_data_en;
    assign ip_wr_data_end  = u_wr_data_end;
    assign u_wr_data_rdy   = ip_wr_data_rdy;

    // --- données lues : moitié demandée, tournée pour que le mot demandé soit en tête -----------------------------
    wire [3:0]   tag_r  = tags[tq_r[TAG_LOG2-1:0]];
    wire [127:0] rhalf  = tag_r[3] ? ip_rd_data[255:128] : ip_rd_data[127:0];
    assign u_rd_data       = rotr128(rhalf, tag_r[2:0]);
    assign u_rd_data_valid = ip_rd_data_valid;
    assign u_rd_data_end   = ip_rd_data_end;
endmodule
`default_nettype wire
"}

